class Node {
    var next: Node?
    deinit { print("deinit") }
}
var a: Node? = Node()
var b: Node? = Node()
a?.next = b
b?.next = a
a = nil
b = nil

class Tracker {
    deinit { print("gone") }
}
func test() {
    let t = Tracker()
    _ = t
}
test()
print("after")

class A {
    weak var b: B?
}
class B {
    var a: A?
    deinit { print("B gone") }
}
var a: A? = A()
var b: B? = B()
a?.b = b
b?.a = a
a = nil
b = nil
